using System.Diagnostics;

public class TracedAiPipeline
{
    private static readonly ActivitySource s_activitySource = new("LearnAI.GenAI.Tracer", "1.0.0");

    public async Task<string> ExecuteAgentTaskAsync(string prompt, CancellationToken ct = default)
    {
        // 1. Start root activity representing the AI operation
        using Activity? activity = s_activitySource.StartActivity(
            name: "gen_ai.client.chat",
            kind: ActivityKind.Client);

        if (activity != null)
        {
            activity.SetTag("gen_ai.system", "azure_openai");
            activity.SetTag("gen_ai.request.model", "gpt-4o");
            activity.SetTag("gen_ai.request.temperature", 0.2);
        }

        try
        {
            // Perform model call
            var response = await CallDownstreamModelAsync(prompt, ct);

            // Enrich span with completion metadata
            activity?.SetTag("gen_ai.usage.input_tokens", response.InputTokens);
            activity?.SetTag("gen_ai.usage.output_tokens", response.OutputTokens);
            activity?.SetTag("gen_ai.response.finish_reasons", new[] { "stop" });

            return response.Text;
        }
        catch (Exception ex)
        {
            // Record exception details in span
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);
            throw;
        }
    }
}
